"""Build a local evidence viewer from historical outputs without changing scores."""
import argparse,json,html,hashlib
from pathlib import Path

STYLE='''
:root{font-family:Segoe UI,Microsoft YaHei,sans-serif;color:#182333;background:#f4f6f8;line-height:1.6;--accent:#155da6;--red:#a52b23;--border:#d5dce5}*{box-sizing:border-box}body{margin:0}a{color:var(--accent)}button,select,input{font:inherit}button,select{min-height:44px}button,a,select{touch-action:manipulation}button{cursor:pointer}:focus-visible{outline:3px solid #155da6;outline-offset:3px}header{background:#142b43;color:white;padding:28px max(24px,4vw)}header h1{margin:6px 0;font-size:clamp(26px,3vw,40px)}header p{max-width:1100px;margin:8px 0;color:#e0e9f4}.metrics{display:flex;gap:14px;flex-wrap:wrap;margin-top:20px}.metric{background:#ffffff12;border:1px solid #ffffff44;border-radius:8px;padding:12px 18px}.metric strong{font-size:28px;margin-right:9px}main{max-width:1800px;margin:auto;padding:24px}.notice{border-left:4px solid #ad640e;background:#fff4de;padding:14px 20px;margin-bottom:20px}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;position:sticky;top:0;z-index:2;background:#f4f6f8;padding:14px 0}select{max-width:100%;padding:8px;border:1px solid var(--border);border-radius:6px;background:white}.toolbar a{margin-left:auto}.samples{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:20px}.samples button{background:white;border:1px solid var(--border);border-radius:5px;padding:6px 13px}.samples button[aria-pressed=true]{background:var(--accent);color:white}.comparison{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.panel{min-width:0;background:white;border:1px solid var(--border);border-radius:8px;overflow:hidden}.panel h3{margin:0;padding:15px;border-bottom:1px solid var(--border);font-size:18px}.media{height:390px;display:flex;align-items:center;justify-content:center;background:white;padding:14px;overflow:hidden}.media img{width:100%;height:100%;object-fit:contain}.media a{height:100%;width:100%;display:block}.empty{padding:24px;background:#faf0ef;color:#72221d;overflow-wrap:anywhere}.status{padding:14px;border-top:1px solid var(--border);min-height:120px}.pill{display:inline-block;border-radius:4px;background:#fae5e3;color:#85241d;padding:3px 8px;font-weight:600;font-size:14px}.pill.limited{background:#e3edf7;color:#154f85}.links{display:flex;gap:15px;flex-wrap:wrap;margin-top:9px}.detail{background:white;border:1px solid var(--border);border-radius:8px;margin-top:18px;padding:20px}.detail h3{margin-top:0}.detail li{margin:9px 0;overflow-wrap:anywhere}.detail code{font-size:14px;white-space:pre-wrap;overflow-wrap:anywhere}.detail details{margin:12px 0}.detail summary{cursor:pointer;min-height:44px;padding:8px 0}.muted{color:#536173}footer{padding:20px 0;color:#536173}dialog{width:96vw;max-width:1800px;height:94vh;border:1px solid var(--border);border-radius:8px;padding:18px}dialog::backdrop{background:#000b}.zoomhead{display:flex;justify-content:space-between;align-items:center;gap:12px}.zoomhead button{padding:8px 20px}.zoomscroll{height:calc(100% - 70px);overflow:auto;text-align:center;background:#f1f3f5;margin-top:12px}.zoomscroll img{max-width:100%;height:auto;background:white}.zoomscroll.actual img{max-width:none}button.secondary{border:1px solid var(--border);background:white;border-radius:5px;padding:8px 14px}@media(max-width:1000px){.comparison{grid-template-columns:1fr}.media{height:360px}.toolbar{position:static}.status{min-height:0}}@media(max-width:480px){main{padding:16px}.metric{padding:8px 12px}.metric strong{font-size:23px}.media{height:290px}}@media(prefers-reduced-motion:no-preference){button,a{transition:background-color .15s,color .15s}}'''

JS=r'''
const rows=DATA.rows,select=document.querySelector('#sample'),tabs=document.querySelector('#samples'),out=document.querySelector('#case');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(p,label)=>p?`<a href="${esc(p)}" target="_blank" rel="noopener">${label}</a>`:'';
function panel(title,asset,state,links){return `<section class="panel"><h3>${title}</h3><div class="media">${asset?`<a href="${esc(asset)}" data-zoom="${esc(asset)}" aria-label="放大${title}"><img src="${esc(asset)}" alt="${esc(title)}" loading="eager"></a>`:`<div class="empty"><strong>本轮没有可展示的CAD图</strong><p>JSON / 编译阶段失败，保留真实失败状态，未补画替代结果。</p></div>`}</div><div class="status">${state}<div class="links">${links}</div></div></section>`}
function render(id){const r=rows.find(x=>x.id===id)||rows[0];select.value=r.id;location.replace('#'+r.id);tabs.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.id===r.id)));let b=r.scores.baseline,f=r.scores.final;let failures=(b.failures||[]).flatMap(x=>x.failures||[]);out.innerHTML=`<h2>${esc(r.id)} · ${esc(r.title)}</h2><div class="comparison">${panel('原件 · 厂家公开图',r.assets.original,'<span class="pill limited">原始输入</span><p class="muted">独立保留，点击图片可放大。</p>',link(r.source,'厂家来源')+link(r.assets.original,'原图文件'))}${panel('初审 · 第一次模型输出',r.assets.baseline,`<span class="pill">${esc(b.status)}</span><p>${b.error?'未形成有效CAD：'+esc(b.error):`${b.checks}项检查，${b.failed}项未通过`}</p>`,link(r.assets.baseline_dxf,'首轮DXF')+link(r.assets.baseline_plan,'首轮JSON')+link(r.assets.baseline_evidence,'首轮实测 / 错误'))}${panel('终版 · 多轮反馈修复后',r.assets.final,`<span class="pill limited">已覆盖规则通过 · 仍有限制</span><p>${f.checks}项检查，${f.failed}项未通过；不是初次成功。</p>`,link(r.assets.final_dxf,'终版DXF')+link(r.assets.final_plan,'终版JSON')+link(r.assets.final_evidence,'终版实测'))}</div><section class="detail"><h3>初审具体未通过项</h3>${b.error?`<p>${esc(b.error)}</p>`:failures.length?`<ul>${failures.map(v=>`<li><strong>${esc(v.requirement?.view||v.view||'')} / ${esc(v.kind||v.requirement?.kind||v.id)}</strong> · ${esc(v.id)}${v.reason?`<p>${esc(v.reason)}</p>`:''}<details><summary>查看实际测量与规则</summary><code>${esc(JSON.stringify({actual:v.actual,requirement:v.requirement},null,2))}</code></details></li>`).join('')}</ul>`:'<p>未取得逐项失败证据，待核实；不按打开文件推断正确。</p>'}<h3>终版仍未覆盖 / 需人工确认</h3><ul>${r.unresolved.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>本样本累计模型调用 ${r.model_calls.length} 次。终版是在反馈中暴露数值目标后形成的开发回归结果；不代表独立读图能力、完整装配覆盖或制造验收。</p><div class="links">${link(r.assets.result,'本例完整记录')}</div></section>`;out.querySelectorAll('[data-zoom]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();document.querySelector('#zoomimg').src=a.dataset.zoom;document.querySelector('#zoomtitle').textContent=a.getAttribute('aria-label');document.querySelector('#zoom').showModal()}));}
rows.forEach((r,i)=>{const o=document.createElement('option');o.value=r.id;o.textContent=`${i+1}. ${r.title}`;select.append(o);const b=document.createElement('button');b.textContent=String(i+1).padStart(2,'0');b.dataset.id=r.id;b.setAttribute('aria-label',r.title);b.addEventListener('click',()=>render(r.id));tabs.append(b)});
select.addEventListener('change',()=>render(select.value));document.querySelector('#closezoom').onclick=()=>document.querySelector('#zoom').close();document.querySelector('#actual').onclick=()=>{const p=document.querySelector('.zoomscroll');p.classList.toggle('actual');document.querySelector('#actual').setAttribute('aria-pressed',String(p.classList.contains('actual')))};
window.addEventListener('hashchange',()=>{if(select.value!==location.hash.slice(1))render(location.hash.slice(1))});render(location.hash.slice(1));
'''

def build(output,benchmark):
 output=Path(output).resolve();benchmark=Path(benchmark).resolve()
 summary=json.loads((output/'summary.json').read_text(encoding='utf-8'));records=[];checks=[]
 for row in summary['rows']:
  cid=row['id'];assets={}
  paths={'original':output/cid/'original.png','baseline':output/cid/'baseline'/f'{cid}_deepseek_harness.png','baseline_dxf':output/cid/'baseline'/f'{cid}_deepseek_harness.dxf','baseline_evidence':output/cid/'baseline'/('error.json' if row['scores']['baseline'].get('error') else 'acceptance.json'),'final':output/cid/'final'/f'{cid}_deepseek_harness.png','final_dxf':output/cid/'final'/f'{cid}_deepseek_harness.dxf','final_plan':output/cid/'final/model_plan.json','final_evidence':output/cid/'final/acceptance.json','result':output/cid/'result.json'}
  plan=benchmark/'cases'/cid/'runs/baseline/round-01/plan.json'
  if plan.exists():
   # Link the retained response without copying or editing it.
   import os
   assets['baseline_plan']=Path(os.path.relpath(plan,output)).as_posix()
  for key,path in paths.items():
   assets[key]=path.relative_to(output).as_posix() if path.exists() else None
   if path.exists():checks.append({'path':str(path),'sha256':hashlib.sha256(path.read_bytes()).hexdigest()})
  for required in ['original','final','final_dxf','baseline_evidence']:
   if not assets[required]:raise ValueError(f'Missing evidence {cid}: {required}')
  if assets['baseline_dxf'] and not assets['baseline']:raise ValueError(f'Existing baseline DXF requires an actual render: {cid}')
  if row['scores']['baseline']['status']=='COMPILE_OR_JSON_FAILED' and assets['baseline']:raise ValueError('Do not label a later drawing as initial failed output')
  records.append({**row,'assets':assets})
 data=json.dumps({**summary,'rows':records},ensure_ascii=False).replace('<','\\u003c')
 body='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CAD十图 · 原件 / 初审 / 终版</title><style>STYLE</style><header><div>DEEPSEEK CAD · 历史开发集</div><h1>原件、初审与终版，逐张对照</h1><p>首轮和终版按同一套最终 v7 规则复核。终版接受了数值反馈和多轮修复，不是一次读图成功。</p><div class="metrics"><div class="metric"><strong>0 / 10</strong>首轮整张通过</div><div class="metric"><strong>10 / 10</strong>修复后有限范围通过</div><div class="metric"><strong>74</strong>累计模型调用</div><div class="metric"><strong>0 / 10</strong>完整制造验收</div></div></header><main><div class="notice">这是历史10图的证据展示，不是新增20图的成绩。公差、未知尺寸、完整装配语义等仍有缺口；无首轮有效CAD的样本直接显示失败。</div><nav class="toolbar" aria-label="样本选择"><label for="sample">选择图纸</label><select id="sample"></select><a href="summary.json">历史结果索引</a><a href="index.html">原交付页</a></nav><nav class="samples" id="samples" aria-label="图纸快捷编号"></nav><article id="case" aria-live="polite"></article><footer>实际接口返回型号：deepseek-flash。原件为已获准使用的厂家公开图。本页在本机打开，无外部脚本、字体或上传接口；尚未部署发布。</footer></main><dialog id="zoom" aria-labelledby="zoomtitle"><div class="zoomhead"><strong id="zoomtitle">图纸放大</strong><button class="secondary" id="actual" aria-pressed="false">切换原始像素</button><button class="secondary" id="closezoom">关闭</button></div><div class="zoomscroll"><img id="zoomimg" alt="放大图纸"></div></dialog><script>const DATA=DATA_JSON;JS_SOURCE</script></html>'''
 page=body.replace('STYLE',STYLE).replace('DATA_JSON',data).replace('JS_SOURCE',JS)
 (output/'review.html').write_text(page,encoding='utf-8')
 result={'rows':len(records),'originals':sum(bool(x['assets']['original']) for x in records),'baseline_images':sum(bool(x['assets']['baseline']) for x in records),'baseline_without_valid_cad':sum(not x['assets']['baseline'] for x in records),'final_images':sum(bool(x['assets']['final']) for x in records),'linked_evidence':checks,'score_source':str(output/'summary.json'),'historical_scores_unchanged':True,'deployment':'LOCAL_ONLY'}
 (output/'review-page-check.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
 return result

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output',required=True);p.add_argument('--benchmark',required=True);a=p.parse_args();r=build(a.output,a.benchmark);print(json.dumps({k:v for k,v in r.items() if k!='linked_evidence'},ensure_ascii=False))
